// 1. Access the data using the modern $json syntax
const content = $json.data || ""; 

// 2. Extract YAML Front Matter
const yamlMatch = content.match(/^---\s*([\s\S]*?)\s*---/);
if (!yamlMatch) return { skip: true };

const yamlLines = yamlMatch[1].split('\n');
const metadata = {};
let currentKey = null;

yamlLines.forEach(line => {
    const trimmed = line.trim();
    if (trimmed.startsWith('-') && currentKey) {
        if (!Array.isArray(metadata[currentKey])) metadata[currentKey] = [];
        metadata[currentKey].push(line.replace('-', '').trim().replace(/^["']|["']$/g, ''));
    } else {
        const parts = line.split(':');
        if (parts.length >= 2) {
            currentKey = parts[0].trim();
            let value = parts.slice(1).join(':').trim();
            // Inline array syntax, e.g. ["a", "b"] or [a, b]
            if (value.startsWith('[') && value.endsWith(']')) {
                const inner = value.slice(1, -1).trim();
                metadata[currentKey] = inner.length === 0
                    ? []
                    : inner.split(',').map(v => v.trim().replace(/^["']|["']$/g, ''));
            } else {
                metadata[currentKey] = value.replace(/^["'\s]+|["'\s]+$/g, '');
            }
        }
    }
});

// 3. Stage B Filter: Only 'active' or 'delivered' or 'paused' (paused included so housekeeping projects appear)
const validStatuses = ['active', 'delivered', 'paused', 'ongoing'];
if (!validStatuses.includes(metadata.status)) return { skip: true };

// 4. Extract "## Current Status" — full section, no truncation
const currentStatus = (content.split(/## Current Status/i)[1]?.split(/^##/m)[0] || '').trim();

// 5. Extract "## Tasks"
const taskSection = content.split(/## Tasks/i)[1]?.split(/^##/m)[0] || "";
const openTasks = taskSection.match(/- \[ \].*/g) || [];
const completedTasks = taskSection.match(/- \[x\].*/g) || [];
const fileNameRaw = $("Split Out").item.json.files || "Untitled";

// 6. Normalise priority — default to 🟢 ON THE RADAR if not set
const rawPriority = (metadata.priority || '').trim();
let priority;
if (rawPriority.includes('\uD83D\uDD34')) {
    priority = '\uD83D\uDD34 URGENT';
} else if (rawPriority.includes('\uD83D\uDFE1')) {
    priority = '\uD83D\uDFE1 IMPORTANT';
} else if (rawPriority.includes('\uD83D\uDD35')) {
    priority = '\uD83D\uDD35 HOUSEKEEPING';
} else {
    priority = '\uD83D\uDFE2 ON THE RADAR';
}

// 7. Paused projects only flow through if they are HOUSEKEEPING priority
if (metadata.status === 'paused' && priority !== '\uD83D\uDD35 HOUSEKEEPING') return { skip: true };

// 8. Parse milestone dates — null if missing or empty
const parseMilestone = (val) => {
    if (!val || val === 'null' || val.trim() === '') return null;
    return val.trim();
};

// 9. Normalise ClickUp chat channel IDs — combine clickup_channel_id (singular)
// and clickup_channel_ids (array) into a single deduped array
const channelIds = new Set();
if (metadata.clickup_channel_id && typeof metadata.clickup_channel_id === 'string') {
    channelIds.add(metadata.clickup_channel_id);
}
if (Array.isArray(metadata.clickup_channel_ids)) {
    metadata.clickup_channel_ids.forEach(id => { if (id) channelIds.add(id); });
} else if (typeof metadata.clickup_channel_ids === 'string' && metadata.clickup_channel_ids) {
    channelIds.add(metadata.clickup_channel_ids);
}

// 10. Final JSON Output
return {
    id: metadata.id || "unknown-id",
    job_name: metadata.job_name || "Untitled Project",
    file_name: fileNameRaw.replace('.md', ''), 
    status: metadata.status,
    priority: priority,
    keywords: Array.isArray(metadata.keywords) ? metadata.keywords : [],
    slack_channel: metadata.slack_channel || null,
    clickup_channel_ids: Array.from(channelIds),
    milestone_offline: parseMilestone(metadata.milestone_offline),
    milestone_online: parseMilestone(metadata.milestone_online),
    milestone_delivery: parseMilestone(metadata.milestone_delivery),
    current_status: currentStatus.length > 0 ? currentStatus : "No recent status update.",
    open_tasks: openTasks.map(t => t.replace('- [ ] ', '').trim()),
    completed_tasks: completedTasks.map(t => t.replace('- [x] ', '').trim())
};
